    term_limit:                           { column: 'presidential_term_limit',              value: GAME_CONFIG.PRESIDENTIAL_TERM_LIMIT,  label: 'Presidential Term Limits',     cooldown: GAME_CONFIG.TERM_LIMIT_COOLDOWN_TICKS,                  proposedCol: 'proposed_term_limit' },
