const ENDORSEMENT_SWITCH_WINDOW_TICKS = 6;
const ENDORSEMENT_SWITCH_WINDOW_ERROR = `Endorsements can only be changed in the last ${ENDORSEMENT_SWITCH_WINDOW_TICKS} ticks before a presidential election.`;

function isEndorsementSwitchWindowOpen(currentTick, nextPresidentialTick) {
    if (!Number.isFinite(currentTick) || !Number.isFinite(nextPresidentialTick)) return false;
    const ticksUntilElection = nextPresidentialTick - currentTick;
    return ticksUntilElection >= 1 && ticksUntilElection <= ENDORSEMENT_SWITCH_WINDOW_TICKS;
}
/**
 * Update GAME_CONFIG with nation-specific seat values.
 * Call after loading the nation on each page.
 *
 * Always resets to defaults (120) when nation data is missing, so that
 * sequential multi-nation tick processing never leaks one nation's seat
 * count into the next nation's calculations.
 */
/**
 * Get the effective presidential term length (in ticks) for a nation.
 * Uses nation-specific override if set, otherwise falls back to GAME_CONFIG default.
 */
function getPresidentialTermTicks(nation) {
    if (nation && nation.presidential_term_ticks != null && nation.presidential_term_ticks > 0) {
        return nation.presidential_term_ticks;
    }
    return GAME_CONFIG.PRESIDENTIAL_TERM_TICKS;
}

/**
 * Get the effective presidential term limit for a nation.
 * Uses nation-specific override if set (including 0 for no limits),
 * otherwise falls back to GAME_CONFIG default.
 * Returns null if no limits (0 stored or explicitly set to unlimited).
 */
function getPresidentialTermLimit(nation) {
    if (nation && nation.presidential_term_limit !== null && nation.presidential_term_limit !== undefined) {
        return nation.presidential_term_limit === 0 ? null : nation.presidential_term_limit;
    }
    return GAME_CONFIG.PRESIDENTIAL_TERM_LIMIT;
}

/**
 * Get the effective parliamentary term length (in ticks) for a nation.
 * Uses nation-specific override if set, otherwise falls back to GAME_CONFIG default.
 */
function getParliamentaryTermTicks(nation) {
    if (nation && nation.parliamentary_term_ticks != null && nation.parliamentary_term_ticks > 0) {
        return nation.parliamentary_term_ticks;
    }
    return GAME_CONFIG.PARLIAMENTARY_TERM_TICKS;
}

function initGameConfigForNation(nation) {
    const seats = (nation && nation.total_seats) ? nation.total_seats : 120;
    GAME_CONFIG.TOTAL_SEATS = seats;
    GAME_CONFIG.MAJORITY_SEATS = Math.floor(seats / 2) + 1;
}

const FORMATION_DEADLINE_TICKS = 3; // ticks per formation window — applied both pre- and post-snap

/**
 * AP system has been deprecated (Phase A of removal — see CLAUDE.md history).
 *
 * deductAP / accumulateAP are now no-ops that always succeed without
 * touching the database. Every JS callsite (rallies, attacks, press
 * conferences, ministry actions, etc.) keeps working without code
 * changes; the cost simply isn't applied. The DB column, table, and
 * RPCs are still in place for Phase A — they're stripped in Phase C.
 *
 * The `ledger` argument is accepted and ignored so callers don't need
 * to be updated. The returned shape matches the old success path so
 * `if (result.success)` branches still take the happy path.
 */
async function deductAP(_supabase, _factionId, _cost, _ledger) {
    return { success: true, newAp: 0 };
}

async function accumulateAP(_supabase, _factionId, _gain, _maxAp) {
    return { success: true, newAp: 0 };
}

/**
 * Atomically switch a party endorsement target.
 *
 * Server-side RPC behavior:
 * - Reads the existing endorsement preference
 * - Deducts 1 AP only if switching from an existing different target
 * - Upserts the preference row
 *
 * Returns { success: true, newAp, endorsedPartyId } on success.
 */
async function switchPartyEndorsement(supabase, endorsingPartyId, newEndorsedPartyId, currentTick) {
    const { data, error } = await supabase.rpc('switch_party_endorsement', {
        endorsing_party_id: endorsingPartyId,
        new_endorsed_party_id: newEndorsedPartyId,
        current_tick: currentTick
    });

    if (error) {
        console.error('[switchPartyEndorsement] RPC failed:', error.message);
        const rpcMessage = String(error.message || '');
        if (rpcMessage.includes('last 6 ticks before a presidential election')) {
            return { success: false, error: ENDORSEMENT_SWITCH_WINDOW_ERROR };
        }
        return { success: false, error: error.message };
    }

    const row = Array.isArray(data) ? data[0] : data;
    return {
        success: true,
        newAp: row?.updated_ap,
        endorsedPartyId: row?.endorsed_party_id
    };
}

// ────────── government-types ──────────

/**
 * government-types — Government type helpers (democracy, presidential, monarchy)
 *
 * Semi-presidential was culled in 20270748. No nation in use ran it
 * and the cohabitation / domain-split machinery (MINISTRY_DOMAINS,
 * EO_DOMAIN, isCohabitation, isPresidentialDomainMinistry,
 * getMinistryDomain, isSemiPresidential) was dead weight. Anything
 * that used to branch on isSemiPresidential is now either the
 * presidential branch or the parliamentary branch.
 */

/**
 * Government type helpers.
 * Call with a nation object (must have government_type field).
 */
const CANONICAL_GOVERNMENT_TYPES = Object.freeze({
    PARLIAMENTARY_DEMOCRACY: 'Democracy',
    PRESIDENTIAL_REPUBLIC: 'Presidential',
    ABSOLUTE_MONARCHY: 'Absolute Monarchy'
});

const GOVERNMENT_TYPE_ALIASES = Object.freeze({
    democracy: CANONICAL_GOVERNMENT_TYPES.PARLIAMENTARY_DEMOCRACY,
    democratic: CANONICAL_GOVERNMENT_TYPES.PARLIAMENTARY_DEMOCRACY,
    parliamentary: CANONICAL_GOVERNMENT_TYPES.PARLIAMENTARY_DEMOCRACY,
    parliamentarian: CANONICAL_GOVERNMENT_TYPES.PARLIAMENTARY_DEMOCRACY,
    'parliamentary democracy': CANONICAL_GOVERNMENT_TYPES.PARLIAMENTARY_DEMOCRACY,
    presidential: CANONICAL_GOVERNMENT_TYPES.PRESIDENTIAL_REPUBLIC,
    'presidential republic': CANONICAL_GOVERNMENT_TYPES.PRESIDENTIAL_REPUBLIC,
    'executive presidency': CANONICAL_GOVERNMENT_TYPES.PRESIDENTIAL_REPUBLIC,
    'absolute monarchy': CANONICAL_GOVERNMENT_TYPES.ABSOLUTE_MONARCHY,
    'absolute_monarchy': CANONICAL_GOVERNMENT_TYPES.ABSOLUTE_MONARCHY,
    monarchy: CANONICAL_GOVERNMENT_TYPES.ABSOLUTE_MONARCHY,
});

function getCanonicalGovernmentType(input, fallbackType = CANONICAL_GOVERNMENT_TYPES.PARLIAMENTARY_DEMOCRACY) {
    const govType = typeof input === 'string' ? input : input?.government_type;
    if (typeof govType !== 'string') return fallbackType;
    return GOVERNMENT_TYPE_ALIASES[govType.trim().toLowerCase()] || fallbackType;
}

function isParliamentaryDemocracy(input) { return getCanonicalGovernmentType(input) === CANONICAL_GOVERNMENT_TYPES.PARLIAMENTARY_DEMOCRACY; }
function isPresidentialRepublic(input) { return getCanonicalGovernmentType(input) === CANONICAL_GOVERNMENT_TYPES.PRESIDENTIAL_REPUBLIC; }
function isAbsoluteMonarchy(input) { return getCanonicalGovernmentType(input) === CANONICAL_GOVERNMENT_TYPES.ABSOLUTE_MONARCHY; }
// KNOWN GAP: Monarchy nations have no elections. Seats are currently static.
// Future Phase 4: Add "Grant Seats" royal action for monarch to appoint seats to noble houses.

/** Capability helpers — thin aliases over the type predicates. Kept
 *  because callers read more cleanly as "does this nation have an
 *  elected president?" / "does this nation have a parliamentary PM?"
 *  than as direct type checks. */
function hasElectedPresident(input) { return isPresidentialRepublic(input); }
function hasParliamentaryPM(input) { return isParliamentaryDemocracy(input) || isAbsoluteMonarchy(input); }
function hasMonarch(input) { return isAbsoluteMonarchy(input); }

/** Get the head of state title for display */
function getHeadOfStateTitle(nation) {
    if (isAbsoluteMonarchy(nation)) return nation.monarch_title || 'King';
    if (hasElectedPresident(nation)) return 'President';
    return nation.hos_title || 'Head of State';
}

function isGovernmentPresidential(nation) { return hasElectedPresident(nation); }

